//! Owner4 bindings share Raw44 allocation/global state with all other effects.
use crate::{Game,Value,json,original_combat::OriginalRng,original_audio::Gate};
use super::{State,effects::{self,Particle,bridge,spray::{Context,Pool}},trail::{self,raw_set,raw_word,raw_ptr}};
const BUILD:u32=0x5c5e38;
const FRAGMENTS:u32=0x596b16;
fn globals(s:&State)->bridge::Globals{bridge::Globals{context:Context{origin:s.effect_origin,tint:s.effect_tint,flags:s.effect_flags,fade:s.effect_fade,owner:s.effect_owner,sprite:s.effect_sprite},maximum:s.effect_maximum as u8,suppression:s.effect_suppression,raw:s.bridge_fx}}
fn commit(s:&mut State,g:bridge::Globals){s.effect_origin=g.context.origin;s.effect_tint=g.context.tint;s.effect_flags=g.context.flags;s.effect_fade=g.context.fade;s.effect_owner=g.context.owner;s.effect_sprite=g.context.sprite;s.effect_maximum=g.maximum as i8;s.effect_suppression=g.suppression;s.bridge_fx=g.raw;}
struct World<'a>{state:&'a mut State,rng:&'a mut OriginalRng}
impl Pool for World<'_>{
 fn first_free(&self)->Option<usize>{self.state.effects.iter().position(|p|p.as_ref().is_none_or(|p|!p.active||p.position[0]==-1000))}
 fn load(&mut self,slot:usize)->[u8;44]{self.state.effects[slot].as_ref().map_or([0;44],Particle::bytes)}
 fn store(&mut self,slot:usize,r:[u8;44]){self.state.put_effect(slot,Particle::from_bytes(r));}
 fn random(&mut self)->u32{self.rng.next_u32()}
}
impl bridge::World for World<'_>{fn retire(&mut self,slot:usize){if let Some(p)=&mut self.state.effects[slot]{p.active=false;p.position[0]=-1000;}}}
impl Game{
 ///The Main audio reset is owned by begin_native_spatial_audio_main;
 ///this separate Owner4 hook clears only the retained trail draw rows.
 pub(crate)fn begin_native_owner4_main(&mut self){if let Some(s)=&mut self.native_world{s.trail_draws.clear();}}
 ///460430 initializes all four scene headers to-1.423140 returns0 without
 ///a child callback when all are-1/0; active cutscene handlers remain explicit.
 pub(crate)fn native_trail_scene_result(&mut self)->Option<u8>{let s=self.native_world.as_mut()?;if self.native_display.scene_mode!=0&&s.trail_scenes.iter().all(|v|*v== -1){s.trail.boundary=Some(trail::Boundary{address:0x622b90,length:80});return None;}for(i,v)in s.trail_scenes.iter_mut().enumerate(){if *v==-1||*v==0{continue;}*v=v.wrapping_add(1);if *v==170{*v=-1;return Some(1);}s.trail.boundary=Some(trail::Boundary{address:0x622b90+i as u32*20,length:20});return None;}Some(0)}

 pub(super)fn import_native_trail_buildings(&mut self,v:&Value){let Some(rows)=v["nativeWorldBuildings"].as_array().filter(|v|v.len()==35)else{return;};let disk=(0..35).map(|i|{let row=rows.iter().find(|r|r["nativeSlot"].as_u64()==Some(i))?;let bytes=row["nativeDisk80"].as_array().filter(|r|r.len()==80)?;let mut out=[0;80];for(b,v)in out.iter_mut().zip(bytes){*b=u8::try_from(v.as_u64()?).ok()?;}Some(out)}).collect::<Option<Vec<_>>>();if let(Some(s),Some(d))=(&mut self.native_world,disk){s.trail.load_buildings(&d);}}
 pub(super)fn initialize_native_trail_build_constructor(&mut self,slot:usize,f:crate::original_factory::ConstructorFields){let Some(s)=&mut self.native_world else{return;};if slot>=35||!s.trail.known_builds[slot]{return;}let Some(r)=s.buildings.get(slot)else{return;};let Some(ordinal)=s.fragments.bindings[slot]else{return;};let b=&mut s.trail.builds[slot];raw_set(b,0,r.record.position[0]);raw_set(b,2,r.record.position[1]);b[4]=r.record.kind as u8;raw_set(b,30,r.record.hp);raw_set(b,28,r.record.hp);b[32..36].fill(0);b[58]=f.door3a as u8;for n in[10,54,60]{raw_set(b,n,0);}raw_set(b,8,-1);b[17..22].fill(0);b[53]=2;b[7]=255;b[82..87].fill(255);b[6]&=224;b[57]=0;b[69]=0;b[40..48].fill(0);b[76..80].fill(255);let timer=raw_word(b,80);if timer!=-1{b[76..80].copy_from_slice(&i32::from(timer).wrapping_mul(1700).to_le_bytes());}let p=FRAGMENTS+ordinal as u32*900;b[24..28].copy_from_slice(&p.to_le_bytes());b[64..68].copy_from_slice(&p.to_le_bytes());b[6]=f.flags6;if let Some(n)=f.style5{b[5]=n;}if let Some(n)=f.field10{b[16]=n;}b[17]=f.field11;if let Some(n)=f.clock3e{b[62]=n;}b[69]=f.state45;if let Some(n)=f.remaining24{b[36..40].copy_from_slice(&n.to_le_bytes());}if let Some(p)=self.native_strategy.as_ref().and_then(|st|st.sector_pointer(f64::from(r.record.position[0])*2.,f64::from(r.record.position[1])*2.)){b[32..36].copy_from_slice(&p.to_le_bytes());}}
 pub(super)fn native_building_particle_prefix(&mut self,state:&mut State,slot:usize){let Some(b)=state.buildings.get(slot)else{return;};let(kind,p)=(b.record.kind,b.record.position);let Some((header,_))=trail::header(kind)else{return;};state.trail.headers[slot]=Some(header);if state.trail.known_builds[slot]{let b=&mut state.trail.builds[slot];raw_set(b,30,0);b[48..52].copy_from_slice(&header.to_le_bytes());}let mut arena=std::mem::take(&mut state.trail);let mut g=globals(state);self.original_rng.multiplayer=self.multiplayer;if let Err(e)=trail::prefix(&mut arena,&mut World{state,rng:&mut self.original_rng},&mut g,kind,p){arena.boundary=Some(e);}state.trail=arena;commit(state,g);}
 pub(super)fn finish_native_building_part_expiry(&mut self,slot:usize,_view:effects::View){
  let Some(s)=&self.native_world else{return;};let Some(p)=s.effects.get(slot).and_then(Option::as_ref)else{return;};let point=[p.origin[0].wrapping_add(s.last_projection[0]),p.origin[1].wrapping_add(s.last_projection[1])];self.emit_native_spatial_audio(crate::original_audio::spatial::Chance::Owner4Expiry3{point});
  if let Some(s)=&mut self.native_world{s.effect_world_suppression=1;}if point[0]>=-32{self.native_building_part_blast(point);}if let Some(s)=&mut self.native_world{s.effect_world_suppression=0;}
  self.native_direct_environment_contact([point[0].wrapping_sub(10),point[1].wrapping_sub(5),point[0].wrapping_add(54),point[1].wrapping_add(41)],50);
  //Both calls above may reenter BUILD destruction and replace shared globals.
  let Some(s)=&mut self.native_world else{return;};let Some(p)=s.effects.get(slot).and_then(Option::as_ref)else{return;};let point=[p.origin[0].wrapping_add(s.last_projection[0]),p.origin[1].wrapping_add(s.last_projection[1])];let mut g=globals(s);self.original_rng.multiplayer=self.multiplayer;trail::expiry_children(&mut World{state:s,rng:&mut self.original_rng},&mut g,slot,point);commit(s,g);
 }
 pub(crate)fn native_building_trail_draws(&self)->Vec<Value>{self.native_world.as_ref().map_or_else(Vec::new,|s|s.trail_draws.clone())}
 ///435fde receives the actual423140 result; nonzero skips the whole reader.
 pub(crate)fn update_native_building_trails(&mut self,result:u8){let Some(s)=&mut self.native_world else{return;};s.trail_draws.clear();s.trail_main_result=Some(result);if result!=0{return;}let(camera,size)=self.native_view.unwrap_or(([0,0],[(self.map.width*16)as i16,(self.map.height*16)as i16]));let Some(sprites)=bridge::engine_sprites(self.map.world)else{return;};let view=trail::View{camera,size,clip_min:[0,0],quality:s.effect_quality,world_base:sprites.prefix};
  for slot in 0..64{let s=self.native_world.as_ref().unwrap();let j=s.trail.jobs[slot];if j.ptr(0)==0{continue;}let bridge_mode=s.trail.word(j.ptr(0)).is_ok_and(|v|v as u16&128!=0);let bi=j.ptr(4).wrapping_sub(BUILD)as usize/88;let step=self.native_world.as_mut().unwrap().trail.playback(slot,view);let step=match step{Ok(v)=>v,Err(e)=>{self.native_world.as_mut().unwrap().trail.boundary=Some(e);continue;}};
   for d in step.draws{let row=json!({"id":slot,"source":"buildingTrail","stage":"late","nativeInheritedPalette":true,"sprite":d.sprite,"x":i32::from(d.position[0])*2,"y":i32::from(d.position[1])*2,"scale":0.5,"rotation":f64::from((f32::from(d.angle)*2.*3.1415925f32)*0.00390625),"nativeDrawX":d.screen[0],"nativeDrawY":d.screen[1]});self.native_world.as_mut().unwrap().trail_draws.push(row);}
   if step.frame==Some(7){if let Some(point)=self.native_late_trail_target(j.ptr(4),bridge_mode){self.emit_native_late_build_audio(crate::original_audio::late_build::Stage::Frame7,point);}}
   if let Some(job)=step.bridge_complete{if !self.finish_native_bridge_job(job.ptr(4)){continue;}if let Err(e)=self.native_world.as_mut().unwrap().trail.complete(slot,job.ptr(0)){self.native_world.as_mut().unwrap().trail.boundary=Some(e);}}
   if let Some(job)=step.restore{if !self.restore_native_trail_building(bi){continue;}if let Some(point)=self.native_late_trail_target(job.ptr(4),false){self.emit_native_late_build_audio(crate::original_audio::late_build::Stage::BuildComplete,point);}if let Err(e)=self.native_world.as_mut().unwrap().trail.complete(slot,job.ptr(0)){self.native_world.as_mut().unwrap().trail.boundary=Some(e);}}
  }self.finish_native_late_build_audio_reader();
 }
 ///Read the actual current target record, without HP/liveness or Web fallback.
 fn native_late_trail_target(&mut self,pointer:u32,bridge_mode:bool)->Option<[i16;2]>{let s=self.native_world.as_mut()?;let point=if bridge_mode{let offset=pointer.wrapping_sub(super::crane_bridge::BASE);(offset%32==0).then(||s.bridges.iter().find(|b|b.native_slot==offset as usize/32).map(|b|b.record.position)).flatten()}else{let offset=pointer.wrapping_sub(BUILD);let i=offset as usize/88;if offset%88==0&&i<35&&s.trail.known_builds[i]{Some([raw_word(&s.trail.builds[i],0),raw_word(&s.trail.builds[i],2)])}else{None}};if point.is_none(){s.trail.boundary=Some(trail::Boundary{address:pointer,length:if bridge_mode{32}else{88}});}point}

 fn restore_native_trail_building(&mut self,slot:usize)->bool{let Some(s)=&mut self.native_world else{return false;};if slot>=35||!s.trail.known_builds[slot]{s.trail.boundary=Some(trail::Boundary{address:BUILD.wrapping_add(slot as u32*88),length:88});return false;}let mut b=s.trail.builds[slot];self.original_rng.multiplayer=self.multiplayer;let mut crt=self.native_cosmetic_rng;trail::restore_raw(&mut b,self.multiplayer,||self.original_rng.next_u32(),||{crt=crt.wrapping_mul(214013).wrapping_add(2531011);((crt>>16)&32767)as u16});self.native_cosmetic_rng=crt;
  let Some(ordinal)=s.fragments.bindings[slot]else{s.trail.boundary=Some(trail::Boundary{address:BUILD+slot as u32*88+64,length:4});return false;};let p=[raw_word(&b,0),raw_word(&b,2)];if let Some(t)=&s.fragments.templates[slot]{s.fragments.pools[ordinal].construct(p,t,raw_word(&b,28)/5);}s.fragments.pools[ordinal].clear();s.fragments.starts[slot]=0;let sector=self.native_strategy.as_ref().and_then(|st|st.sector_pointer(f64::from(p[0])*2.,f64::from(p[1])*2.)).unwrap_or(0);trail::restore_tail(&mut b,sector);s.trail.builds[slot]=b;s.buildings[slot].record.hp=raw_word(&b,30);s.buildings[slot].display.word0a=0;s.buildings[slot].display.flags6=b[6];if b[4]==0{s.buildings[slot].repair=Some(super::workshop::State{bytes:b});}if let Some(f)=s.buildings[slot].constructor.as_mut(){f.flags6=b[6];f.style5=Some(b[5]);f.field11=b[17];f.state45=b[69];f.remaining24=Some(0);if b[4]==4{f.field10=Some(b[16]);f.clock3e=Some(b[62]);}}
  if let Some(id)=s.buildings[slot].binding{self.native_factory_flags6.insert(id,b[6]);self.native_factory_work.remove(&id);if let Some(ui)=self.buildings.iter_mut().find(|v|v.id==id){ui.hp=f64::from(raw_word(&b,30));ui.product=None;ui.remaining_work=None;ui.completion_ticks=0;ui.progress=0.;ui.ready_guns.clear();}}let stencil=s.alive_stamps.get(&(b[4]as i8)).cloned();if let Some((pointer,w,h,codes))=stencil{let y=p[1].wrapping_add(if b[4]==0{0}else{32});let y=if[0x47840c,0x47856c,0x47828c].contains(&pointer){y}else{y.wrapping_sub(32)};self.stamp_native_crane_codes(p[0],y,w,h,&codes);}true
 }
}
